// Local mock/demo product data — stands in for a real backend/database
// until one is wired up.
//
// How images become products:
//   For each category, if real photos exist in public/images/<slug>/
//   (tracked by src/data/imageManifest.json, regenerated by
//   `npm run manifest` before every dev/build), a product is generated
//   automatically for every image found there — no code edits needed.
//   The product's display name comes straight from the filename (kebab
//   or snake case is turned into Title Case), so renaming a file is all
//   it takes to rename the poster on the site.
//   Categories with no real photos yet fall back to the curated demo
//   products below, purely so the site isn't empty on a fresh checkout.
import imageManifest from "./imageManifest.json";
import { CATEGORIES, getCategoryName } from "./categories.js";

