// ---------- Turn real photos into products automatically ----------

function filenameToTitle(filename) {
  const stem = filename.replace(/\.[^.]+$/, "");
  return stem
    .replace(/[-_]+/g, " ")
    .trim()
    .split(" ")
    .filter(Boolean)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    .join(" ");
}

// Deterministic "price" derived from the filename so it doesn't jump
// around between manifest rebuilds — stands in for a real price an
// admin would set once a backend exists.
function filenameToPrice(filename) {
  let hash = 0;
  for (let i = 0; i < filename.length; i++) {
    hash = (hash * 31 + filename.charCodeAt(i)) >>> 0;
  }
  const steps = [249, 269, 289, 299, 319, 339, 349, 369, 379, 399, 419, 449, 479, 499];
  return steps[hash % steps.length];
}

function productFromImage(categorySlug, filename, index) {
  return {
    id: `${categorySlug}__${filename}`,
    name: filenameToTitle(filename),
    price: filenameToPrice(filename),
    category: categorySlug,
    image: filename,
    // First photo dropped into each category powers the homepage wall
    // until an admin panel exists to pick featured posters explicitly.
    featured: index === 0,
    description: "",
    reviews: [],
  };
}

function buildCatalog() {
  const catalog = [];
  for (const cat of CATEGORIES) {
    const images = imageManifest[cat.slug] || [];
    if (images.length > 0) {
      images.forEach((filename, i) => catalog.push(productFromImage(cat.slug, filename, i)));
    } else {
      catalog.push(...curatedFallback.filter((p) => p.category === cat.slug));
    }
  }
  return catalog;
}

export const mockProducts = buildCatalog();

export function getProductById(id) {
  return mockProducts.find((p) => p.id === id);
}

export function getProductsByCategory(slug) {
  return mockProducts.filter((p) => p.category === slug);
}

export function getFeaturedProducts() {
  return mockProducts.filter((p) => p.featured);
}

export function getRelatedProducts(product, count = 6) {
  return mockProducts
    .filter((p) => p.category === product.category && p.id !== product.id)
    .slice(0, count);
}

export function searchProducts(query) {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  return mockProducts.filter((p) => {
    if (p.name.toLowerCase().includes(q)) return true;
    // Matches the search hint's promise ("...or a category name") — e.g.
    // typing "tamil" or "marvel" finds everything in that category, which
    // matters most while real photos still carry their original camera-roll
    // filenames and haven't been given a proper poster name yet.
    return getCategoryName(p.category).toLowerCase().includes(q);
  });
}

export function averageRating(product) {
  if (!product.reviews || product.reviews.length === 0) return 0;
  const sum = product.reviews.reduce((acc, r) => acc + r.rating, 0);
  return sum / product.reviews.length;
}
